#!/usr/bin/env node
/**
 * Builds the native SQLite3 database (`data/survival_knowledge.db`) using Node.js 22+/24+ `node:sqlite`
 * from the canonical `data/survival_knowledge_store.json` seed generated by Python.
 */

import { DatabaseSync } from "node:sqlite";
import { existsSync, mkdirSync, readFileSync, rmSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT_DIR = resolve(__dirname, "..");
const DATA_DIR = resolve(ROOT_DIR, "data");
mkdirSync(DATA_DIR, { recursive: true });

const jsonPath = resolve(DATA_DIR, "survival_knowledge_store.json");
const dbPath = resolve(DATA_DIR, "survival_knowledge.db");

if (!existsSync(jsonPath)) {
  console.error("Seed JSON introuvable :", jsonPath);
  process.exit(1);
}

const store = JSON.parse(readFileSync(jsonPath, "utf-8"));
if (existsSync(dbPath)) {
  rmSync(dbPath);
}

const db = new DatabaseSync(dbPath);
db.exec(`
  CREATE VIRTUAL TABLE manuals_fts USING fts5(
    id UNINDEXED,
    title,
    category,
    source,
    tags,
    content
  );

  CREATE TABLE botanical_guardrails (
    id TEXT PRIMARY KEY,
    common_name TEXT,
    scientific_name TEXT,
    toxicity_level TEXT,
    lookalikes TEXT,
    warning TEXT
  );

  CREATE TABLE survival_pois (
    id TEXT PRIMARY KEY,
    name TEXT,
    category TEXT,
    osm_tag TEXT,
    lat REAL,
    lon REAL,
    elevation_m INTEGER,
    notes TEXT
  );
`);

const insManual = db.prepare(
  "INSERT INTO manuals_fts (id, title, category, source, tags, content) VALUES (?, ?, ?, ?, ?, ?)"
);
for (const m of store.manuals) {
  insManual.run(m.id, m.title, m.category, m.source, m.tags, m.content);
}

const insBot = db.prepare(
  "INSERT INTO botanical_guardrails VALUES (?, ?, ?, ?, ?, ?)"
);
for (const b of store.botanical_guardrails) {
  insBot.run(b.id, b.common_name, b.scientific_name, b.toxicity_level, b.lookalikes, b.warning);
}

const insPoi = db.prepare(
  "INSERT INTO survival_pois VALUES (?, ?, ?, ?, ?, ?, ?, ?)"
);
for (const p of store.pois) {
  insPoi.run(p.id, p.name, p.category, p.osm_tag, p.lat, p.lon, p.elevation_m, p.notes);
}

db.close();
console.log(`[SQLite FTS5] Base créée avec succès : ${dbPath} (${store.manuals.length} manuels, ${store.botanical_guardrails.length} garde-fous, ${store.pois.length} POI OSM)`);

